public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes accent color and background custom emoji of a channel chat. Requires can_change_info administrator right
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetChatAccentColorAsync(long chatId = default, int accentColorId = default, long backgroundCustomEmojiId = default)
    {

           using var activity =  StartCallActivity("SetChatAccentColorAsync", typeof(SetChatAccentColor).FullName ?? "SetChatAccentColorAsync");

           try
           {
             return client.SetChatAccentColorAsync(chatId, accentColorId, backgroundCustomEmojiId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
